int sctp_get_assoc_stats(struct sock *sk, int len, char __user *optval, int __user *optlen) {
    struct sctp_association *asoc = sctp_id2assoc(sk);
    struct sctp_assoc_stats stats = {0};
    int ret = 0;

    if (!asoc) {
        return -EINVAL;
    }

    if (len < sizeof(stats)) {
        return -EINVAL;
    }

    if (put_user(sizeof(stats), optlen)) {
        return -EFAULT;
    }

    stats.assoc_id = asoc->assoc_id;
    stats.cumu_flight = asoc->c.s.snd_flight_size;
    stats.a_rwnd = asoc->a_rwnd;
    stats.u_rwnd = asoc->u_rwnd;
    stats.rwnd_limit = asoc->rwnd_limit;
    stats.pd_rint = asoc->pd_rint;
    stats.pd_out = asoc->pd_out;
    stats.pd_wait = asoc->pd_wait;
    stats.retrans_out = asoc->retrans_out;
    stats.retrans_bytes = asoc->retrans_bytes;
    stats.fast_retrans = asoc->fast_retrans;
    stats.sack_delayed = asoc->sack_delayed;
    stats.sack_discarded = asoc->sack_discarded;
    stats.sndbuf_alloc = asoc->sndbuf_alloc;
    stats.sndbuf_used = asoc->sndbuf_used;
    stats.sndbuf_freed = asoc->sndbuf_freed;
    stats.max_rto = asoc->rto;

    if (copy_to_user(optval, &stats, sizeof(stats))) {
        return -EFAULT;
    }

    return 0;
}
